const updateRemediation = `-- name: UpdateRemediation :exec
UPDATE remediations SET
    state = $1,
    intent_revision = $2,
    base_sha = $3,
    branch = $4,
    expected_head = $5,
    reserved_until = $6,
    pr_number = $7,
    pr_url = $8,
    proposal = $9,
    hold = $10,
    closed_at = $11,
    close_reason = $12,
    last_run_at = now()
WHERE id = $13
`

type UpdateRemediationParams struct {
	State          string
	IntentRevision string
	BaseSha        *string
	Branch         *string
	ExpectedHead   *string
	ReservedUntil  *time.Time
	PrNumber       *int32
	PrUrl          *string
	Proposal       json.RawMessage
	Hold           *string
	ClosedAt       *time.Time
	CloseReason    *string
	ID             int64
}

// The remediator's columns of a claimed row; the evaluator's
// observation columns are never written here (DESIGN-0032 AR-0032-01).
func (q *Queries) UpdateRemediation(ctx context.Context, arg UpdateRemediationParams) error {
	_, err := q.db.Exec(ctx, updateRemediation,
		arg.State,
		arg.IntentRevision,
		arg.BaseSha,
		arg.Branch,
		arg.ExpectedHead,
		arg.ReservedUntil,
		arg.PrNumber,
		arg.PrUrl,
		arg.Proposal,
		arg.Hold,
		arg.ClosedAt,
		arg.CloseReason,
		arg.ID,
	)
	return err
}

const upsertRemediateInstallation = `-- name: UpsertRemediateInstallation :exec
INSERT INTO app_installations (app, installation_id, account_login, account_type, repository_selection, seen_at)
VALUES ('remediate', $1, $2, $3, $4, now())
ON CONFLICT (app, installation_id) DO UPDATE SET
    account_login = EXCLUDED.account_login,
    account_type = EXCLUDED.account_type,
    repository_selection = EXCLUDED.repository_selection,
    seen_at = EXCLUDED.seen_at
`

type UpsertRemediateInstallationParams struct {
	InstallationID      int64
	AccountLogin        string
	AccountType         string
	RepositorySelection string
}

// The Remediation App's discovery refreshes its own installation rows
// (RLS app_installations_remediate). Suspension is left to the
// lifecycle events, which the listing does not carry.
func (q *Queries) UpsertRemediateInstallation(ctx context.Context, arg UpsertRemediateInstallationParams) error {
	_, err := q.db.Exec(ctx, upsertRemediateInstallation,
		arg.InstallationID,
		arg.AccountLogin,
		arg.AccountType,
		arg.RepositorySelection,
	)
	return err
}
